    fn stub_ctx(command_succeeds: bool, network_ok: bool) -> InstallerContext<'static> {
        let run_cmd: &'static dyn Fn(&str) -> bool = if command_succeeds {
            &|_| true
        } else {
            &|_| false
        };
        let net: &'static dyn Fn() -> bool = if network_ok { &|| true } else { &|| false };
        InstallerContext {
            run_command: run_cmd,
            check_network: net,
            prepend_path: &|_| {},
        }
    }

