        env.insert("API_KEY".to_string(), "key-value".to_string());

        let auth = resolve_auth("header", "API_KEY", Some("X-API-Key"), &env);

        assert!(auth.is_some());
        let auth = auth.unwrap();
        assert_eq!(auth.header_name, "X-API-Key");
        assert_eq!(auth.header_value, "key-value");
